const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').split(/\s+/).filter(t => t.length > 0);

const N = +tokens[0];
const M = +tokens[1];
const K = +tokens[2];
const senha = tokens[3];

// Ordena as letras de cada palavra (a i-ésima palavra corresponde à i-ésima letra borrada)
const words = [];
for (let i = 0; i < M; i++) {
  words.push(tokens[4 + i].split('').sort());
}
const P = +tokens[4 + M];

// Como todas as senhas têm o mesmo comprimento e mesmas letras fixas,
// a ordem lexicográfica equivale a ordenar as escolhas das posições borradas
// da esquerda para a direita. Logo, P-1 em base K com M dígitos dá a escolha
// de cada posição borrada (dígito mais significativo = primeira borrada).
let index = P - 1;
const digits = new Array(M).fill(0);
for (let j = M - 1; j >= 0; j--) {
  digits[j] = index % K;
  index = Math.floor(index / K);
}
// Nota: para K === 1, todos os dígitos são 0 (única senha possível, P = 1),
// e o loop acima produz exatamente isso sem problema.

let out = '';
let wi = 0;
for (let i = 0; i < N; i++) {
  const c = senha[i];
  if (c === '#') {
    out += words[wi][digits[wi]];
    wi++;
  } else {
    out += c;
  }
}

process.stdout.write(out + '\n');
